(function () {
  "use strict";

  var DEFAULT_COLORS = {
    concept: "#3b82f6",
    tool: "#22c55e",
    decision: "#f59e0b",
    error: "#ef4444",
    service: "#8b5cf6",
    person: "#10b981",
    incident: "#f43f5e",
    reference: "#94a3b8",
  };
  var FALLBACK_COLOR = "#64748b";

  var instances = new Map();
  var pendingData = new Map();

  function getColor(colorMap, type) {
    return colorMap[type] || DEFAULT_COLORS[type] || FALLBACK_COLOR;
  }

  function init() {
    if (typeof ForceGraph3D === "undefined") return;

    document
      .querySelectorAll("[data-tui-graph]:not([data-tui-graph-initialized])")
      .forEach(function (el) {
        var id = el.id;
        if (!id) return;

        var dataURL = el.getAttribute("data-tui-graph-data-url");
        var bg = el.getAttribute("data-tui-graph-bg") || "transparent";
        var colorMap = {};
        try {
          colorMap = JSON.parse(
            el.getAttribute("data-tui-graph-color-map") || "{}"
          );
        } catch (e) {
          // malformed JSON in color-map attribute, use empty map
        }
        var showLabels =
          el.getAttribute("data-tui-graph-labels") === "true";
        var enableExpand =
          el.getAttribute("data-tui-graph-expand") === "true";
        var expandURL =
          el.getAttribute("data-tui-graph-expand-url") || "";
        var controlType =
          el.getAttribute("data-tui-graph-control") || "trackball";
        var onClick = el.getAttribute("data-tui-graph-on-click") || "";
        var clickURL =
          el.getAttribute("data-tui-graph-click-url") || "";

        el.setAttribute("data-tui-graph-initialized", "true");

        // Hide loading placeholder
        var loading = el.querySelector("[data-tui-graph-loading]");

        var graph = new ForceGraph3D(el)
          .backgroundColor(
            bg === "transparent" ? "rgba(0,0,0,0)" : bg
          )
          .nodeColor(function (n) {
            return getColor(colorMap, n.type);
          })
          .nodeVal(function (n) {
            return n.val || 1;
          })
          .nodeLabel(function (n) {
            return n.name || n.id;
          })
          .linkWidth(1)
          .linkOpacity(0.4)
          .linkDirectionalArrowLength(3.5)
          .linkDirectionalArrowRelPos(1)
          .controlType(controlType)
          .onNodeClick(function (node, event) {
            el.dispatchEvent(
              new CustomEvent("tui-graph-node-click", {
                detail: { node: node },
                bubbles: true,
              })
            );
            if (onClick === "slideover" && clickURL) {
              var url = clickURL.replace("{id}", node.id);
              if (typeof htmx !== "undefined") {
                htmx.ajax("GET", url, {
                  target: "#slide-over-body",
                  swap: "innerHTML",
                });
              }
              document.dispatchEvent(
                new CustomEvent("slideover-open", { detail: {} })
              );
            } else if (onClick === "navigate" && clickURL) {
              window.location.href = clickURL.replace("{id}", node.id);
            } else if (
              onClick &&
              typeof window[onClick] === "function"
            ) {
              window[onClick](node, event);
            }

            // Expand neighbors on click if enabled
            if (enableExpand && expandURL) {
              expandNeighbors(id, node.id, expandURL, colorMap);
            }
          })
          .onNodeHover(function (node) {
            el.style.cursor = node ? "pointer" : "default";
            if (node) {
              el.dispatchEvent(
                new CustomEvent("tui-graph-node-hover", {
                  detail: { node: node },
                  bubbles: true,
                })
              );
            }
          });

        if (showLabels) {
          graph
            .nodeThreeObject(function (node) {
              var sprite = new window.SpriteText(node.name || node.id);
              sprite.color = getColor(colorMap, node.type);
              sprite.textHeight = 2;
              return sprite;
            })
            .nodeThreeObjectExtend(false);
        }

        // Fit to view when engine settles
        graph.onEngineStop(function () {
          graph.zoomToFit(400);
        });

        instances.set(id, {
          graph: graph,
          data: null,
          cleanup: function () {
            if (graph._destructor) graph._destructor();
          },
        });

        // Check for pending data (inline mode)
        if (pendingData.has(id)) {
          var data = pendingData.get(id);
          pendingData.delete(id);
          graph.graphData(data);
          if (loading) loading.style.display = "none";
        } else if (dataURL) {
          // Fetch from URL
          fetch(dataURL)
            .then(function (r) {
              return r.json();
            })
            .then(function (data) {
              graph.graphData(data);
              if (loading) loading.style.display = "none";
              instances.get(id).data = data;
            })
            .catch(function (err) {
              console.error("Graph data fetch failed:", err);
              if (loading)
                loading.innerHTML =
                  '<span class="text-xs text-destructive">Failed to load graph</span>';
            });
        }

        // Responsive sizing
        var ro = new ResizeObserver(function () {
          graph.width(el.clientWidth).height(el.clientHeight);
        });
        ro.observe(el);
      });
  }

  function expandNeighbors(graphId, nodeId, expandURLPrefix, colorMap) {
    var inst = instances.get(graphId);
    if (!inst) return;

    var existingIds = new Set(
      inst.graph.graphData().nodes.map(function (n) {
        return n.id;
      })
    );
    var url =
      expandURLPrefix +
      "?node_id=" +
      nodeId +
      "&exclude=" +
      Array.from(existingIds).join(",");

    fetch(url)
      .then(function (r) {
        return r.json();
      })
      .then(function (newData) {
        var current = inst.graph.graphData();
        var mergedNodes = current.nodes.slice();
        var mergedLinks = current.links.slice();
        var nodeSet = new Set(
          current.nodes.map(function (n) {
            return n.id;
          })
        );

        (newData.nodes || []).forEach(function (n) {
          if (!nodeSet.has(n.id)) {
            mergedNodes.push(n);
            nodeSet.add(n.id);
          }
        });
        (newData.links || []).forEach(function (l) {
          mergedLinks.push(l);
        });

        inst.graph.graphData({
          nodes: mergedNodes,
          links: mergedLinks,
        });
      })
      .catch(function (err) {
        console.error("Expand neighbors failed:", err);
      });
  }

  function setData(graphId, data) {
    var inst = instances.get(graphId);
    if (inst) {
      inst.graph.graphData(data);
      inst.data = data;
      var el = document.getElementById(graphId);
      if (el) {
        var loading = el.querySelector("[data-tui-graph-loading]");
        if (loading) loading.style.display = "none";
      }
    } else {
      pendingData.set(graphId, data);
    }
  }

  function destroy(graphId) {
    var inst = instances.get(graphId);
    if (inst) {
      inst.cleanup();
      instances.delete(graphId);
    }
  }

  function getInstance(graphId) {
    return instances.get(graphId);
  }

  // Initialize on DOM ready and after HTMX swaps
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
  document.addEventListener("htmx:afterSwap", init);

  // MutationObserver for dynamically added graphs
  new MutationObserver(function (mutations) {
    for (var i = 0; i < mutations.length; i++) {
      var addedNodes = mutations[i].addedNodes;
      for (var j = 0; j < addedNodes.length; j++) {
        var n = addedNodes[j];
        if (
          n.nodeType === 1 &&
          (n.hasAttribute && n.hasAttribute("data-tui-graph") ||
            n.querySelector && n.querySelector("[data-tui-graph]"))
        ) {
          setTimeout(init, 0);
          return;
        }
      }
    }
  }).observe(document.body, { childList: true, subtree: true });

  window.tui = window.tui || {};
  window.tui.graph = {
    init: init,
    destroy: destroy,
    setData: setData,
    getInstance: getInstance,
  };
})();
